const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function completionReviewPanel(review,{busy=false,dirty=false}={}){
 if(!review||review.status==='generating')return '';
 const confirmed=review.status==='confirmed'&&!dirty,ready=review.status==='ready'&&!dirty;
 const title=dirty?'资料已更新，请重新完善':confirmed?'补充内容已确认':ready?'自动补充完成，请确认内容':review.status==='needs_materials'?'已补充可完成内容，仍需核实资料':'自动补充结果待继续检查';
 return `<section class="thesis-completion-review" data-completion-review data-state="${confirmed?'confirmed':ready?'ready':'pending'}" aria-label="自动补充结果确认"><header><div><small>终稿内容确认</small><h3>${title}</h3></div><span>${(review.changes||[]).length} 个章节已更新</span></header><p>补充后的内容已放入上方章节工作区，原有版本保留。请核对研究事实、数据含义与引用。</p>${review.simulationUsed?'<p class="completion-simulation-note">本稿使用了模拟数据，终稿将保留仿真方法与数据说明。</p>':''}<div class="completion-review-checks">${[['materials','资料依据'],['manuscript','全文检查'],['content','内容完整性']].map(([key,label])=>`<span data-passed="${!dirty&&review.checks?.[key]===true}">${!dirty&&review.checks?.[key]===true?'✓':'·'} ${label}</span>`).join('')}</div><ul class="completion-review-changes" aria-label="自动补充的章节">${(review.changes||[]).map(row=>`<li><div><b>${esc(row.title)}</b><small>${row.kind==='added'?'已补写':'已完善'} · ${Number(row.characters).toLocaleString('zh-CN')} 字符</small></div><button type="button" class="btn secondary" data-completion-view="${esc(row.chapterId)}" ${busy?'disabled':''}>查看内容</button></li>`).join('')}</ul>${review.missing?.length?`<div class="completion-review-missing"><strong>仍需确认的事实资料</strong><p>这些事实无法从现有资料确定，补充后系统会继续写入正文。</p><ul>${review.missing.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>`:''}${review.issues?.length?`<details open><summary>待完善的检查项</summary><ul>${review.issues.map(row=>`<li>${esc(row.title)}：${esc(row.text)}</li>`).join('')}</ul></details>`:''}${review.suggestions?.length?`<details open><summary>表达建议（供确认时参考）</summary><ul>${review.suggestions.map(row=>`<li>${esc(row.title)}：${esc(row.text)}</li>`).join('')}</ul></details>`:''}${ready?`<button type="button" class="btn primary" data-completion-confirm ${busy?'disabled':''}>确认补充内容，编排并导出终稿</button>`:confirmed?'<p role="status">本版本已确认，可在下方下载终稿。内容或模板变化后需重新确认。</p>':'<p>检查尚未通过，当前结果可下载为初稿；补齐下方资料后再次自动完善。</p>'}<p data-completion-confirm-status role="status"></p></section>`;
}
